183	+// The constructor keeps a public named param (`picker`) distinct from
184	+// the private field it initializes, matching `record_mic_recorder.dart`'s
185	+// documented convention.
186	+// ignore_for_file: prefer_initializing_formals
187	+import 'package:image_picker/image_picker.dart' as image_picker_pkg;
188	+
189	+import '../../domain/services/photo_picker.dart';
190	+
191	+/// Wraps `package:image_picker`'s `ImagePicker` behind the [PhotoPicker]
192	+/// port. A `get_it` singleton (Code Map/`capture_injection.dart`) — one
193	+/// real picker for the app's lifetime, reused across every Insertion
194	+/// Modal open, mirroring `RecordMicRecorder`'s own registration shape.
195	+class ImagePickerPhotoPicker implements PhotoPicker {
196	+  ImagePickerPhotoPicker({required image_picker_pkg.ImagePicker picker})
197	+    : _picker = picker;
198	+
199	+  final image_picker_pkg.ImagePicker _picker;
200	+
201	+  @override
202	+  Future<PickedPhoto?> pickFromCamera() =>
203	+      _pick(image_picker_pkg.ImageSource.camera);
204	+
205	+  @override
206	+  Future<PickedPhoto?> pickFromGallery() =>
207	+      _pick(image_picker_pkg.ImageSource.gallery);
208	+
209	+  Future<PickedPhoto?> _pick(image_picker_pkg.ImageSource source) async {
210	+    final file = await _picker.pickImage(source: source);
211	+    if (file == null) {
212	+      return null;
213	+    }
214	+    return PickedPhoto(path: file.path, mimeType: _mimeTypeOf(file.path));
215	+  }
216	+
217	+  /// Inferred from the picked file's extension only — jpeg/png/webp,
218	+  /// matching `media-ocr`'s contract enum exactly (Boundaries). Anything
219	+  /// else (e.g. iOS HEIC, a known gap — Never: "no HEIC→JPEG conversion
220	+  /// or client-side pre-check this story") falls back to `image/jpeg`,
221	+  /// the most common on-device case; a genuinely unsupported format
222	+  /// still surfaces through the backend's own validation rather than a
223	+  /// client-side guess silently mislabeling it.
224	+  String _mimeTypeOf(String path) {
225	+    final extension = path.toLowerCase().split('.').last;
226	+    return switch (extension) {
227	+      'png' => 'image/png',
228	+      'webp' => 'image/webp',
229	+      _ => 'image/jpeg',
230	+    };
231	+  }
232	+}
