752	+          mimeType: mimeType,
753	+          message: failure.message,
754	+          kind: switch (failure) {
755	+            OcrNoText() => PhotoErrorKind.ocrNoText,
756	+            PayloadTooLarge() => PhotoErrorKind.payloadTooLarge,
757	+            _ => PhotoErrorKind.generic,
758	+          },
759	+        ),
760	+      ),
761	+      (ocr) => emit(
762	+        PhotoRecognized(
763	+          path: path,
764	+          mimeType: mimeType,
765	+          text: ocr.text,
766	+          saving: false,
767	+        ),
768	+      ),
769	+    );
770	+  }
771	+
772	+  /// "Tentar novamente" — re-OCRs the same image for an [OcrNoText]
773	+  /// error or a generic OCR-call failure ([PhotoError.text] `null`). A
774	+  /// no-op for [PhotoErrorKind.payloadTooLarge] (I/O matrix: no retry
775	+  /// offered) and for a generic *save* failure (non-null [PhotoError.
776	+  /// text]) — that case's own retry is tapping Salvar again, handled by
777	+  /// [save] directly, mirroring `AudioEntryCubit.retry()`.
778	+  Future<void> retry() async {
779	+    final current = state;
780	+    if (current is! PhotoError ||
781	+        current.text != null ||
782	+        current.kind == PhotoErrorKind.payloadTooLarge) {
783	+      return;
784	+    }
785	+    final generation = ++_generation;
786	+    emit(PhotoProcessing(path: current.path, mimeType: current.mimeType));
787	+    await _recognize(current.path, current.mimeType, generation);
788	+  }
789	+
790	+  /// "Salvar só a foto" — only valid from an [OcrNoText] error; saves the
791	+  /// fixed, non-empty placeholder content (the contract's
792	+  /// `content.minLength: 1` forbids an empty save).
793	+  Future<void> saveWithoutText() async {
794	+    final current = state;
