853	+    }
854	+    await _save(path: path, mimeType: mimeType, text: text);
855	+  }
856	+
857	+  Future<void> _save({
858	+    required String path,
859	+    required String mimeType,
860	+    required String text,
861	+  }) async {
862	+    emit(
863	+      PhotoRecognized(path: path, mimeType: mimeType, text: text, saving: true),
864	+    );
865	+    final result = await _entriesRepository.create(
866	+      content: text,
867	+      source: EntrySource.photo,
868	+    );
869	+    // Mirrors `AudioEntryCubit.save()`'s own `isClosed` guard — this
870	+    // cubit's `close()` can race the awaited call above (e.g. the
871	+    // modal's barrier is dismissed mid-save).
872	+    if (isClosed) {
873	+      return;
874	+    }
875	+    result.match(
876	+      (failure) => emit(
877	+        PhotoError(
878	+          path: path,
879	+          mimeType: mimeType,
880	+          message: failure.message,
881	+          kind: PhotoErrorKind.generic,
882	+          text: text,
883	+        ),
884	+      ),
885	+      (_) {
