103	  Stream<double> get amplitudeStream => _recorder
104	      .onAmplitudeChanged(const Duration(milliseconds: 200))
105	      .map(_normalize);
106	
107	  /// `record`'s own `Amplitude.current` is dBFS, roughly -45 (near
108	  /// silence, in practice — the package's own floor is -160 but normal
109	  /// mic noise never gets that quiet) to 0 (loudest) — rescaled to a
110	  /// 0.0–1.0 range the waveform widget can use directly, with no
111	  /// `package:record` type ever crossing the [MicRecorder] boundary.
112	  double _normalize(record_pkg.Amplitude amplitude) {
113	    const floorDb = -45.0;
114	    final clamped = amplitude.current.clamp(floorDb, 0.0);
115	    return (clamped - floorDb) / -floorDb;
116	  }
